// Sprawdź, czy współrzędne istnieją i czy są równe 0
if (typeof msg.lat !== 'undefined' && typeof msg.lon !== 'undefined') {
    // Uwaga: Porównujemy z 0. Wartości z ESP32 przychodzą jako liczby.
    // Jeśli lat i lon to dokładnie 0 (brak fixa), usuwamy je z obiektu.
    if (msg.lat === 0 && msg.lon === 0) {
        delete msg.lat;
        delete msg.lon;
        delete msg.vel;
        delete msg.alt;
    }
}

return {msg: msg, metadata: metadata, msgType: msgType};

