configuration.jsScript:
// --- CZĘŚĆ 1: Obsługa błędów (Error Code) ---
var code = msg.ec || 0;
var statusList = [];

if (code === 0) {
    msg.status_text = "System OK";
} else {
    // Logika bitowa zgodna z SensorData.h
    if ((code & 1) > 0) statusList.push("Brak Fixa");
    if ((code & 2) > 0) statusList.push("Awaria Termometru");
    if ((code & 4) > 0) statusList.push("Awaria SD");
    if ((code & 8) > 0) statusList.push("Błąd ThingsBoard");
    
    msg.status_text = statusList.join(" + ");
}

// --- CZĘŚĆ 2: Obsługa źródła czasu (Time Source) ---
var src = msg.ts_source;
var srcStr = "Nieznane";

if (src === 0) {
    srcStr = "Lokalny (Timer)";
} else if (src === 1) {
    srcStr = "WiFi (NTP)";
} else if (src === 2) {
    srcStr = "GPS";
}

msg.ts_source_str = srcStr;

// --- CZĘŚĆ 3: Formatowanie daty z metadanych z korektą strefy czasowej ---
if (metadata.ts) {
    var ts = parseInt(metadata.ts);
    
    // KONFIGURACJA: Przesunięcie czasowe (Polska Zima = 1h, Lato = 2h)
    var offsetHours = 1; 
    
    // Dodajemy przesunięcie w milisekundach (godziny * 60 min * 60 sek * 1000 ms)
    var localTs = ts + (offsetHours * 60 * 60 * 1000);
    
    var date = new Date(localTs);
    
    // Teraz toISOString() zwróci czas "przesunięty", czyli zgodny z Twoim zegarkiem
    msg.ts_formatted = date.toISOString().replace('T', ' ').substring(0, 19);
}

// --- FINALIZACJA ---
return {msg: msg, metadata: metadata, msgType: msgType};

// Tworzymy nowy obiekt tylko dla atrybutów
var newMsg = {};

// Sprawdzamy, czy w telemetrii przyszły nasze kluczowe dane
// I przepisujemy je do nowej wiadomości
if (msg.ec !== undefined) {
    newMsg.ec = msg.ec;
}
if (msg.ts_source !== undefined) {
    newMsg.ts_source = msg.ts_source;
}

// Jeśli w wiadomości nie było ani error_code ani time_source, przerywamy
if (Object.keys(newMsg).length === 0) {
    return null;
}

// Zmieniamy typ wiadomości na "Atrybuty" i zwracamy wynik
return {
    msg: newMsg,
    metadata: metadata,
    msgType: 'POST_ATTRIBUTES_REQUEST'
};

